def tokens(s):
    return re.findall(r'GSE\d+|[A-Z][A-Z0-9]{2,}|[-−]?\d+(?:[.,]\d+)*(?:\s*[×x]\s*10[⁻−-]?[⁰¹²³⁴⁵⁶⁷⁸⁹0-9]+)?',s)

d=Document(SRC)
before=[]; after=[]
for i,p in enumerate(d.paragraphs):
    if p.style.name=='List Number':
        continue
    old=p.text
    if not old.strip(): continue
    new=P.get(i,old)
    for a,b in R.items(): new=new.replace(a,b)
    # Remove only dispensable template transitions; preserve causal connectors inside statistical reasoning.
    new=new.replace('在这里，我们','本研究').replace('自始至终，我们','文中').replace('值得注意的是，','')
    if new!=old:
        before.extend(tokens(old)); after.extend(tokens(new))
        p.clear(); p.add_run(new)

d.core_properties.title='PDE8B与肺动脉高压平滑肌重塑及环核苷酸程序：中文人工润色版'
d.save(OUT)
audit={'source_tokens':len(before),'output_tokens':len(after),'missing':sorted(set(before)-set(after)),'added':sorted(set(after)-set(before))}
(ROOT/'manuscript'/'humanizer_zh_audit.json').write_text(json.dumps(audit,ensure_ascii=False,indent=2),encoding='utf-8')
print(OUT); print(json.dumps(audit,ensure_ascii=False))
